{"content": "import sys; sys.path.insert(0,'src')
import pandas as pd, numpy as np
from fleetrisk import io_layer
cfg={'paths':{'data_dir':'data'}}
flights = io_layer.read_flights(cfg); groundings = io_layer.read_groundings(cfg)

def label_for(loi, hii):
    out = flights.copy()
    j = out[['tail_number','departed_at']].reset_index().merge(
        groundings[['tail_number','occurred_at']], on='tail_number', how='left')
    d = (j.occurred_at - j.departed_at).dt.total_seconds()
    w = 3*86400
    if loi and hii: hit=(d>=0)&(d<=w)
    elif loi: hit=(d>=0)&(d<w)
    elif hii: hit=(d>0)&(d<=w)
    else: hit=(d>0)&(d<w)
    lab=hit.groupby(j['index']).any()
    out['label']=lab.reindex(out.index).fillna(False).astype(int)
    return out.sort_values('flight_id',kind='stable').reset_index(drop=True)

def _window(df, spec):
    lo=pd.Timestamp(spec['from']); hi=pd.Timestamp(spec['to'])+pd.Timedelta(days=1)-pd.Timedelta(seconds=1)
    return df[(df.departed_at>=lo)&(df.departed_at<=hi)]
sc_spec={'from':'2024-02-05','to':'2024-02-08'}
print('target mean_score = 0.011374, watch_rate=0.027683 -> 687 of 24817')
for loi in [False,True]:
    for hii in [False,True]:
        lb=label_for(loi,hii)
        sc=_window(lb,sc_spec)
        print('lbl(%s,%s): score positive rate=%.6f n=%d positives=%d'%(loi,hii,sc.label.mean(),len(sc),sc.label.sum()))
print('DONE',flush=True)
